prompt --application/shared_components/security/authorizations/is_1_user
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(5596229416654607440)
,p_name=>'is_1__USER'
,p_static_id=>'is-1-user'
,p_scheme_type=>'NATIVE_EXISTS'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'sql_query', wwv_flow_string.join(wwv_flow_t_varchar2(
    'select 1',
    '  from MD_USERS_V u',
    ' where upper( u.USERNAME ) = upper( :APP_USER )',
    '   and u.ROLE IN (''ANALYST'', ''APPROVER'', ''CONTROLLER'', ''OPERATIONS_ANALYST'', ''OPERATIONS_MANAGER'', ''SUPPORT'', ''DIRECTOR'', ''ADMINISTRATOR'' )')))).to_clob
,p_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3 style="text-align: center;">',
'   <span style="font-family: verdana,geneva,sans-serif; color: #ff0000; font-size: 14px;">',
'      Your are not authorized to use this page of the application!',
'   </span>',
'</h3>',
'<p>',
'   <span style="font-size: 14px; font-family: verdana,geneva,sans-serif;">',
'      <span style="background-color: #00ffff;">',
'         <strong>',
'            This page is available to users with the roles: ',
'            <span style="color: #ff0000;"> ANALYST</span> or',
'            <span style="color: #ff0000;"> APPROVER</span> or',
'            <span style="color: #ff0000;"> FINANCIAL CONTROLLER</span> or',
'            <span style="color: #ff0000;"> OPERATIONS_ANALYST</span> or',
'            <span style="color: #ff0000;"> OPERATIONS_MANAGER</span> or',
'            <span style="color: #ff0000;"> SUPPORT</span> or',
'            <span style="color: #ff0000;"> DIRECTOR</span> or',
'            <span style="color: #ff0000;"> ADMINISTRATOR</span>!',
'         </strong>',
'      </span>',
'      <br /> &nbsp;<br />',
'      <span style="font-size: 11px; font-family: verdana,geneva,sans-serif;">',
'         <strong>',
'            In order to get access to this APEX-tool, you need to request your access via OIM!',
'         </strong>',
'         <br /> &nbsp;<br />',
'         <ul>',
'            <li>Please log into OIM at <a href="https://oim.oraclecorp.com/" target="blank">the link</a></li>',
'            <li>Click on "Request Access ", "Request for self"</li>',
'            <li>Search "Payroll APEX" =&gt; click on "Add to Cart" following "button Next"</li>',
'            <li>Under panel "Details" use magnifying glass icon and select desired role for your region following with "OK"</li>',
'            <li>Fill in the "Justification" box and click on "Ready to submit" button.</li>',
'            <li>Click on "Submit"</li>',
'         </ul>',
'      </span>',
'   </span>',
