 p_id=>wwv_flow_imp.id(5569935705591349509)
,p_lov_name=>'LOV_COUNTRIES'
,p_static_id=>'lov-countries'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select cnt.COUNTRY || nvl2( cnt.BRANCH , '' '' || cnt.BRANCH , '''' ) as d',
'     , cnt.ID as r',
'  from MD_COUNTRIES  cnt',
'     , MD_USERS_V    u',
' where cnt.DELETED_SIGN is NULL',
'   and cnt.COUNTRY is NOT NULL',
'   and (cnt.REGION = u.REGION or u.REGION is NULL)',
'   and upper(u.USERNAME) = upper(:APP_USER)',
' order by 1'))
,p_source_type=>'LEGACY_SQL'
,p_location=>'LOCAL'
,p_version_scn=>'1'
);
end;
