,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select SHORT_NAME as d',
'     , SHORT_NAME as r',
'  from ( select e.SHORT_NAME',
'               , e.FOR_TEAM',
'            from CAL_DIC_EVENTS e',
'               , MD_USERS_V     u',
'           where upper(u.USERNAME) = upper(:APP_USER)',
'             and (    ( e.FOR_TEAM = ''USER''        and u.ROLE in (''ADMINISTRATOR'', ''OPERATIONS_MANAGER'', ''OPERATIONS_ANALYST'', ''DIRECTOR'', ''SUPPORT'', ''APPROVER'', ''ANALYST'', ''CONTROLLER'') )',
'                   or ( e.FOR_TEAM = ''PAN_APP_OPR'' and u.ROLE in (''ADMINISTRATOR'', ''OPERATIONS_MANAGER'', ''OPERATIONS_ANALYST'', ''DIRECTOR'', ''SUPPORT'', ''APPROVER'', ''ANALYST''              ) )',
'                 )',
'       )'))
,p_source_type=>'LEGACY_SQL'
,p_location=>'LOCAL'
,p_version_scn=>'1'
);
