wwv_flow_imp_page.create_region_column(
 p_id=>wwv_flow_imp.id(5604664077564419252)
,p_name=>'APPROVE_FLAG'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'APPROVE_FLAG'
,p_data_type=>'VARCHAR2'
,p_session_state_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_RADIOGROUP'
,p_heading=>'Approval<br>Status<br><button type=''button'' class=''t-Button t-Button--icon t-Button--noLabel header-button js-actionButton'' data-action=''selection-copy-down'' title=''Copy Down''><span class=''fa fa-clone fam-arrow-down''></span></button>'
,p_label=>'Approval Status'
,p_heading_alignment=>'CENTER'
,p_display_sequence=>140
,p_value_alignment=>'LEFT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_is_required=>true
,p_lov_type=>'SQL_QUERY'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d, r',
'  from (',
'-- Initial Labels',
'select ''New''       as d, ''NEW'' as r from dual where :OLD_APPROVE_FLAG is null',
'union all',
'select ''Deleted''   as d, ''DEL'' as r from dual where :OLD_APPROVE_FLAG in (''DEL'')',
'union all',
'select ''New''       as d, ''NEW'' as r from dual where :OLD_APPROVE_FLAG in (''NEW'')',
'union all',
'select ''Rejected''  as d, ''REJ'' as r from dual where :OLD_APPROVE_FLAG in (''REJ'')',
'-- union all',
'-- select ''Submitted'' as d, ''SUB'' as r from dual where :OLD_APPROVE_FLAG in (''SUB'')',
'-- union all',
'-- select ''Approved''  as d, ''APR'' as r from dual where :OLD_APPROVE_FLAG in (''APR'')',
'union all',
'select ''Withdrawn'' as d, ''WIT'' as r from dual where :OLD_APPROVE_FLAG in (''WIT'')',
'union all',
'',
'-- Available Options',
'select ''Delete''   as d, ''DEL'' as r from dual where :OLD_APPROVE_FLAG in (''NEW'', ''REJ'')',
'-- union all',
'-- select ''Approve''  as d, ''APR'' as r from dual where :OLD_APPROVE_FLAG in (''SUB'')',
'-- union all',
'-- select ''Reject''   as d, ''REJ'' as r from dual where :OLD_APPROVE_FLAG in (''SUB'')',
'union all',
'select ''Submit''   as d, ''SUB'' as r from dual where :OLD_APPROVE_FLAG in (''NEW'', ''REJ'', ''WIT'')',
'-- union all',
'-- select ''Withdraw'' as d, ''WIT'' as r from dual where :OLD_APPROVE_FLAG in (''APR'')',
'union all',
'select ''Undelete'' as d, ''NEW'' as r from dual where :OLD_APPROVE_FLAG in (''DEL'')',
'       )',
'',
''))
,p_lov_display_extra=>false
,p_lov_display_null=>false
,p_lov_cascade_parent_items=>'OLD_APPROVE_FLAG'
,p_ajax_optimize_refresh=>true
,p_filter_is_required=>false
,p_use_as_row_header=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    // This doesn''t work until 5.1.1',
'    config.defaultGridColumnOptions = {',
'        headingCssClasses: "has-button"',
'    }',
'    return config;',
'}',
''))
,p_enable_hide=>true
,p_is_primary_key=>false
,p_default_type=>'STATIC'
,p_default_expression=>'NEW'
,p_duplicate_value=>true
,p_include_in_export=>true
,p_escape_on_http_output=>true
);
