,p_parent_plug_id=>wwv_flow_imp.id(6771578508022307284)
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent1:t-Region--scrollBody'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(5569639897346850164)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.COUNTRY_CODE2',
'     , c.COUNTRY_NAME',
'     , c.START_DATE',
'     , c.END_DATE',
'     , ''<div class="phoca-box"><div class="phoca-flagbox"><span class="phoca-flag '' || lower( c.COUNTRY_CODE2 ) || ''"></span></div></div>'' || apex_escape.html( c.COUNTRY_CODE2 || '' - '' || c.SHORT_NAME ) as TITLE',
'     , apex_escape.html( c.FULL_NAME ) as DESCRIPTION',
'     , THE_YEAR || '' - '' || THE_MONTH || '' - '' || PAY_TYPE as CYCLE_NAME',
'     , apex_escape.html( c.CSS_CLASS ) as CSS_CLASS',
'     , apex_escape.html( c.FOR_TEAM ) as FOR_TEAM',
'  from CAL_PAY_CALENDAR_EVENT_V c',
'     , MD_COUNTRIES f',
'     , MD_USERS_V u',
' where  c.COUNTRY_ID = f.ID',
'   and (c.COUNTRY_ID in ( select regexp_substr( :P20_SET_VAL, ''[^:]+'', 1, level)',
'                             from dual connect by regexp_substr( :P20_SET_VAL, ''[^:]+'', 1, level) is not null',
'                        )           or :P20_SET_VAL is null )',
'   and (c.COUNTRY_ID = :P20_COUNTRY or :P20_COUNTRY is null )',
'   and (f.SUB_REGION = :P20_SUBREG  or :P20_SUBREG  is null )',
'   and (f.HUB        = :P20_HUB     or :P20_HUB     is null )',
'   and upper(u.USERNAME) = upper(:APP_USER)',
'   and (f.REGION     = u.REGION     or u.REGION     is null )',
'   and (c.SHORT_NAME in ( select regexp_substr( :P20_PAYTASK, ''[^:]+'', 1, level)',
'                            from dual connect by regexp_substr( :P20_PAYTASK, ''[^:]+'', 1, level) is not null',
'                        ) or :P20_PAYTASK is null )',
'',
'',
'',
'/*',
'select c.COUNTRY_CODE2',
'     , c.COUNTRY_NAME',
'     , c.START_DATE',
'     , c.END_DATE',
'     , ''<div class="phoca-box"><div class="phoca-flagbox"><span class="phoca-flag '' || lower( c.COUNTRY_CODE2 ) || ''"></span></div></div>'' || apex_escape.html( c.COUNTRY_CODE2 || '' - '' || c.SHORT_NAME ) as TITLE',
'     , apex_escape.html( c.FULL_NAME ) as DESCRIPTION',
'     , THE_YEAR || '' - '' || THE_MONTH || '' - '' || PAY_TYPE as CYCLE_NAME',
'     , apex_escape.html( c.CSS_CLASS ) as CSS_CLASS',
'     , apex_escape.html( c.FOR_TEAM ) as FOR_TEAM',
'  from CAL_PAY_CALENDAR_EVENT_V c',
'     , MD_COUNTRIES f',
'     , MD_USERS_V u',
' where  c.COUNTRY_ID = f.ID',
'   and (c.COUNTRY_ID in ( select regexp_substr( :P20_SET_VAL, ''[^:]+'', 1, level)',
'                             from dual connect by regexp_substr( :P20_SET_VAL, ''[^:]+'', 1, level) is not null',
'                        )           or :P20_SET_VAL is null )',
'   and (c.COUNTRY_ID = :P20_COUNTRY or :P20_COUNTRY is null )',
'   and (f.SUB_REGION = :P20_SUBREG  or :P20_SUBREG  is null )',
'   and (f.HUB        = :P20_HUB     or :P20_HUB     is null )',
'   and upper(u.USERNAME) = upper(:APP_USER)',
'   and (    ( c.FOR_TEAM = ''USER''        and u.ROLE in (''ADMINISTRATOR'', ''OPERATIONS_MANAGER'', ''OPERATIONS_ANALYST'', ''DIRECTOR'', ''SUPPORT'', ''APPROVER'', ''ANALYST'', ''CONTROLLER'') )',
'         or ( c.FOR_TEAM = ''PAN_APP_OPR'' and u.ROLE in (''ADMINISTRATOR'', ''OPERATIONS_MANAGER'', ''OPERATIONS_ANALYST'', ''DIRECTOR'', ''SUPPORT'', ''APPROVER'', ''ANALYST''              ) )',
'       )',
'   and (f.REGION     = u.REGION     or u.REGION     is null )',
'*/',
''))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_ajax_items_to_submit=>'P20_PAYTASK,P20_HUB,P20_SUBREG,P20_SET_VAL,P20_COUNTRY'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'additional_calendar_views', 'list:navigation',
  'css_class', 'CSS_CLASS',
  'display_column', 'TITLE',
  'end_date_column', 'END_DATE',
  'event_sorting', 'AUTOMATIC',
  'maximum_events_day', '10',
  'multiple_line_event', 'N',
  'responsive_list_view', 'Y',
  'show_time', 'N',
  'show_tooltip', 'Y',
  'show_weekend', 'N',
  'start_date_column', 'START_DATE',
  'supplemental_information', wwv_flow_string.join(wwv_flow_t_varchar2(
    'Description: &DESCRIPTION.<br>',
    'Country: <b>&COUNTRY_NAME.</b><br>',
    'Cycle name: <b>&CYCLE_NAME.</b>')))).to_clob
);
