,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Init Filters'
,p_static_id=>'init-filters'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_first_set_id     number        ;',
'   v_first_set_val    varchar2(128) ;',
'',
'begin',
'   ',
'   -- Find the first "Country Set" for current user.',
'   select ID into v_first_set_id',
'     from ( select ID',
'              from CAL_PERSONAL_COUNTRY_SETS',
'             where upper( OWNER ) = upper( :APP_USER )',
'          )',
'    where rownum = 1 ;',
'   ',
'   -- Set fields if at least one set was found.',
'   APEX_UTIL.SET_SESSION_STATE(''P20_SET'', v_first_set_id ) ;',
'   ',
'   select COUNTRIES into v_first_set_val',
'     from CAL_PERSONAL_COUNTRY_SETS',
'    where ID = v_first_set_id ;',
'   APEX_UTIL.SET_SESSION_STATE(''P20_SET_val'', v_first_set_val ) ;',
'   ',
'   exception when no_data_found then null ;',
'   ',
'end ;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from dual',
' where :P20_HUB     is NULL',
'   and :P20_SUBREG  is NULL',
'   and :P20_SET     is NULL',
'   and :P20_COUNTRY is NULL',
''))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>5577854445266801881
);
end;
