 p_id=>wwv_flow_imp.id(6804235556081726734)
,p_plug_name=>'Payroll Calendar Report'
,p_static_id=>'payroll-calendar-report'
,p_region_name=>'Cal_Pay'
,p_parent_plug_id=>wwv_flow_imp.id(6804097322359775263)
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent1:t-Region--scrollBody'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(5569639897346850164)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.ID',
'     , f.HUB',
'     , f.SUB_REGION',
'     , c.COUNTRY_ID',
'     , c.THE_YEAR',
'     , c.MONTH_ID',
'     , c.PAY_FREQ_ID',
'     , c.PAY_TYPE_ID',
'     , c.PROCESS_ID',
'     , c.APPROVER',
'     , c.APPROVE_FLAG as OLD_APPROVE_FLAG',
'     , c.APPROVE_FLAG',
'     , c.VISIBLE_FOR_EE',
'     , c.WORK_HOURS',
'     , c.INCENTIVE_CUTOFF_DATE',
'     , c.HRSSC_CUTOFF_DATE',
'     , c.EMPLOYEE_CUTOFF',
'     , c.OTL2HRMS',
'     , c.PTO_TO_HR',
'     , c.VACATION_ACCRUAL',
'     , c.PTO_RUN',
'     , c.BEE_BATCHES',
'     , c.HRMS_INTERFACE_RUN',
'     , c.CUTOFF_DATE_3RDPARTIES',
'     , c.THIRDPARTY_PAYROLL2VENDOR',
'     , c.THIRDPARTY_HANDOVER',
'     , c.THIRDPARTY_ACCEPTANCE',
'     , c.THIRDPARTY_VENDOR2PAYROLL',
'     , c.THIRDPARTY_SIGNOFF',
'     , c.GPAT_FILE',
'     , c.PAYROLL_MGR_GPATREVIEW',
'     , c.GCO_INFORM',
'     , c.BANK_FILE_UPLOAD',
'     , c.THIRDPARTY_CLOSING_DATE',
'     , c.GLFILE_DUEDATE',
'     , c.PAYDAY',
'     , c.KPI_TRACKER',
'     , c.NBA_TOOL',
'     , c.OUTSTANDING_DAYS',
'     , c.COMMENTS',
'     , case when c.APPROVE_FLAG = ''DEL''',
'          then ''DU''',
'          else ''U''',
'       end as ACTIONS_ALLOWED',
'  from CAL_PAY_CALENDAR c',
'     , MD_COUNTRIES     f',
' where   c.COUNTRY_ID = f.ID',
'   and ( c.APPROVE_FLAG in (''SUB'', ''APR'')  or :P30_SAVING is not null )',
'',
'',
'',
'',
'',
'/*',
'  from CAL_PAY_CALENDAR c',
' where ( ( c.APPROVE_FLAG in (''NEW'', ''REJ'', ''WIT'')',
'           and nvl(:P30_YEAR   , c.THE_YEAR   ) = c.THE_YEAR',
'           and nvl(:P30_COUNTRY, c.COUNTRY_ID ) = c.COUNTRY_ID',
'           and c.PAY_TYPE_ID in ( select regexp_substr( :P30_PAYTYPE, ''[^:]+'', 1, level)',
'                                    from dual connect by regexp_substr( :P30_PAYTYPE, ''[^:]+'', 1, level) is not null',
'                                )',
'         )',
'        or :P30_SAVING is not null',
'       )',
'*/',
'/*       ',
'   and c.COUNTRY_ID in ( select f.ID',
'                           from MD_COUNTRIES  f',
'                              , MD_USERS_V    u',
'                          where f.COUNTRY is NOT NULL',
'                            and upper(u.USERNAME) = upper(:APP_USER)',
'                            and nvl(u.REGION, f.REGION) = f.REGION',
'                            and ( ( nvl(:P30_REGION, f.REGION) = f.REGION',
'                                    and nvl(:P30_HUB, f.HUB) = f.HUB',
'                                    and nvl(:P30_SUBREG, f.SUB_REGION) = f.SUB_REGION',
'                                  )',
'                                  or :P30_SAVING is not null',
'                                )',
'                       )',
'',
'*/'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P30_SAVING'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20230217154826Z')
,p_updated_by=>'LUIZA.STANCU@ORACLE.COM'
