,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//  apex.region("IG_Projects").widget().interactiveGrid("getViews", "grid")',
'//  apex.region("IG_Projects").widget().interactiveGrid("option", "config")',
'//',
'',
'function(config) {',
'    config.initActions = function(actions) {',
'        ',
'        // hidding unwanted features',
'        actions.hide("show-aggregate-dialog");',
'        actions.hide("chart-view");',
'        ',
'        // this is part of the hack to avoid the "no data found" error on save',
'        var save = actions.lookup("save"), saveFn = save.action;',
'        save.action = function() {',
'            $s("P30_SAVING", "Y");',
'            // do original save',
'            saveFn();',
'            };        ',
'        ',
'        // add action for "Copy Down" button',
'        actions.add({',
'            name: "selection-copy-down",',
'            label: "Copy Down", // todo use message key',
'            action: function(event, el) {',
'                var i, col, sel, model, val, colName,',
'                    colHeader$ = $(el).closest(".a-GV-header"),',
'                    ig$ = $(actions.context),',
'                    view = ig$.interactiveGrid("getCurrentView");',
'',
'                if ( view.internalIdentifier === "grid" ) {',
'                    // get the column associated with the header the button is in',
'                    col = view.view$.grid("getColumns")[colHeader$.attr("data-idx")];',
'                    sel = view.view$.grid("getSelectedRecords");',
'                    if ( sel.length > 1) {',
'                        colName = col.property;',
'                        model = view.model;',
'                        val = model.getValue(sel[0], colName);',
'                        console.log(">> copy down ", colName, val);                        ',
'                        for( i = 1; i < sel.length; i++) {',
'                            // other variations: check that the column or cell is not readonly or disabled or check that the value is empty',
'                            if ( model.allowEdit( sel[i]) ) {',
'                                model.setValue(sel[i], colName, val);',
'                            }',
'                        }',
'                    }',
'                }                ',
'            }',
'        })',
'    }',
'    return config;',
'}',
'',
''))
,p_updated_on=>wwv_flow_imp.dz('20230217154826Z')
,p_updated_by=>'LUIZA.STANCU@ORACLE.COM'
);
