 p_id=>wwv_flow_imp.id(8069104086713938702)
,p_plug_name=>'Payroll Calendar Editor'
,p_static_id=>'payroll-calendar-editor'
,p_region_name=>'Cal_Pay'
,p_parent_plug_id=>wwv_flow_imp.id(8068965852991987231)
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--accent1:t-Region--scrollBody'
,p_escape_on_http_output=>'N'
,p_plug_template=>wwv_flow_imp.id(5569639897346850164)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.ID',
'     , f.HUB',
'     , f.SUB_REGION',
'     , c.COUNTRY_ID',
'     , c.THE_YEAR',
'     , c.MONTH_ID',
'     , c.PAY_FREQ_ID',
'     , c.PAY_TYPE_ID',
'     , c.PROCESS_ID',
'     , c.APPROVER',
'     , c.APPROVE_FLAG as OLD_APPROVE_FLAG',
'     , c.APPROVE_FLAG',
'     , c.VISIBLE_FOR_EE',
'     , c.COMMENTS',
'     , c.CREATED',
'     , initcap( replace( replace( upper( c.CREATED_BY   ), ''@ORACLE.COM'', '''') , ''.'', '' '') ) as CREATED_BY',
'     , c.UPDATED',
'     , initcap( replace( replace( upper( c.UPDATED_BY   ), ''@ORACLE.COM'', '''') , ''.'', '' '') ) as UPDATED_BY',
'     , c.SUBMITTED',
'     , initcap( replace( replace( upper( c.SUBMITTED_BY ), ''@ORACLE.COM'', '''') , ''.'', '' '') ) as SUBMITTED_BY',
'     , c.APPROVED',
'     , initcap( replace( replace( upper( c.APPROVED_BY  ), ''@ORACLE.COM'', '''') , ''.'', '' '') ) as APPROVED_BY',
'     , case when c.APPROVE_FLAG = ''DEL''',
'          then ''DU''',
'          else ''U''',
'       end as ACTIONS_ALLOWED',
'  from CAL_PAY_CALENDAR c',
'     , MD_COUNTRIES     f',
' where   c.COUNTRY_ID = f.ID',
''))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_updated_on=>wwv_flow_imp.dz('20230213015501Z')
,p_updated_by=>'NANTHIMA.CHUMNUM@ORACLE.COM'
);
wwv_flow_imp_page.create_region_column(
