,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ca.COUNTRY_ID',
'     , ca.HUB',
'     , ca.REGION',
'     , ca.SUBREGION',
'     , ca.COUNTRY',
'     , ca.BRANCH',
'     , ca.LABEL',
'     , ca.THE_YEAR',
'     , ca.ALL_ITEMS',
'     , ca.ITEMS_FOR_EE',
'     , ca.DELETED',
'     , ca.INSERTED',
'     , ca.SUBMITTED',
'     , ca.REJECTED',
'     , ca.WITHDRAWN',
'     , ca.APPROVED',
'  from CAL_PAY_AUDIT_V ca',
'     , MD_USERS_V      u',
' where upper(u.USERNAME) = upper(:APP_USER)',
'   and (ca.REGION   = u.REGION   or u.REGION   is NULL )',
'   and (ca.THE_YEAR = :P110_YEAR or :P110_YEAR is NULL )',
''))
