,p_process_name=>'Init Filters'
,p_static_id=>'init-filters'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_year         integer ;',
'   v_month        integer ;',
'',
'begin',
'   ',
'   select to_number( to_char(sysdate, ''MM'') ) into v_month from dual ;',
'   ',
'   if v_month < 12 then',
'      select to_number( to_char(sysdate, ''YYYY'') ) into v_year from dual ;',
'   else',
'      select to_number( to_char(sysdate, ''YYYY'') ) + 1 into v_year from dual ;',
'   end if ;',
'   ',
'   APEX_UTIL.SET_SESSION_STATE(''P110_YEAR'', v_year ) ;',
'   ',
'end ;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P60_YEAR'
,p_process_when_type=>'ITEM_IS_NULL'
